// AE-03 Worker C: External API Calls
// Receives: { target_api, method, headers, parameters }
// Returns: ApiWorkerResult (Pydantic-compliant)

const input = $input.first().json;
const targetApi = input.target_api || '';
const method = (input.method || 'GET').toUpperCase();
const headers = input.headers || {};
const parameters = input.parameters || {};

// --- Simulated external API call ---
// In production, replace this Code node with an actual
// n8n HTTP Request node pointed at targetApi.

let statusCode = 200;
let responseBody = {};
let success = true;

if (!targetApi) {
  statusCode = 400;
  responseBody = { error: 'No target_api specified' };
  success = false;
} else {
  responseBody = {
    message: `Successfully called ${method} ${targetApi}`,
    request_parameters: parameters,
    mock_data: {
      timestamp: new Date().toISOString(),
      source: 'ae03-worker-api'
    }
  };
}

return [{
  json: {
    status_code: statusCode,
    response_body: responseBody,
    success: success
  }
}];
